        }
        try { cfg = JSON.parse(raw); } catch (e) { return; }
        (function walk(x) {
            if (typeof x === 'string') {
                if (/\.(md|js)$/.test(x) && x.indexOf('/') !== -1) queue.push(rebase(x));
