    if (basePrompts.length > 0) {
        lines.push('## Base cliPrompts');
        lines.push('');
        basePrompts.forEach((entry, idx) => {
            const resolved = resolvePromptEntry(entry);
            if (entry.endsWith('.md')) {
                lines.push(`### [${idx + 1}] \`${entry}\``);
