        var c = buildClosure();
        var files = Object.keys(collectInstructionFiles('instructions'));
        var byDir = {};
        files.forEach(function (f) {
            var d = dirOf(f);
            byDir[d] = byDir[d] || { any: false, missing: [] };
            if (c.reachable[f]) byDir[d].any = true;
